export function FontFamily({
  family = "{{family}}",
  weight = "{{weight}}",
  fontSize = {{fontSize}},
  text = "{{text}}",
}) {
  return (
    <div style={{ color: "#241430", width: 300 }}>
      <p style={{ margin: 0, lineHeight: 1.4, fontFamily: family, fontWeight: Number(weight), fontSize }}>{text}</p>
      <p style={{ marginTop: 12, font: "12px/1.4 system-ui, sans-serif", color: "#241430cc" }}>font-family: {family}</p>
    </div>
  );
}
